// guard exits early when the condition fails
func grade(for score: Int) -> String {
    guard score >= 0, score <= 100 else { return "invalid" }

    switch score {
    case 90...100: return "A"
    case 80..<90: return "B"
    case 70..<80: return "C"
    default: return "F"
    }
}

print(grade(for: 91))

