enum ValidationError: Error {
    case tooShort(minimum: Int)
    case hasDigit
}

func validate(password: String) throws -> Bool {
    guard password.count >= 8 else {
        throw ValidationError.tooShort(minimum: 8)
    }
    guard !password.contains(where: \.isNumber) else {
        throw ValidationError.hasDigit
    }
    return true
}

do {
    try validate(password: "swiftlang")
    print("accepted")
} catch ValidationError.tooShort(let minimum) {
    print("needs at least \(minimum) characters")
} catch {
    print("rejected: \(error)")
}

struct Point {
    var x: Double
    var y: Double

    // Computed property, no stored value
    var magnitude: Double {
        (x * x + y * y).squareRoot()
    }

    // Mutating methods can change stored properties
    mutating func move(by dx: Double, dy: Double) {
        x += dx
        y += dy
    }
}

var point = Point(x: 3, y: 4)
print(point.magnitude)
point.move(by: 1, dy: 0)
print(point.x)

// Copies are independent because Point is a value type
var copy = point
copy.x = 99
print(point.x, copy.x)

