// A generic type stays unconstrained until an extension adds a rule
struct History<Element> {
    private var storage: [Element] = []

    mutating func record(_ element: Element) {
        storage.append(element)
    }
}

extension History where Element: Equatable {
    func contains(_ element: Element) -> Bool {
        storage.contains(element)
    }
}

var history = History<Int>()
history.record(4)
history.record(9)
print(history.contains(9))

