func fetchScore(for player: String) async -> Int {
    try? await Task.sleep(for: .milliseconds(100))
    return player.count * 10
}

// await suspends without blocking the thread
Task {
    let score = await fetchScore(for: "ana")
    print("score: \(score)")
}

// Sequential awaits run one after the other
func combined() async -> Int {
    let first = await fetchScore(for: "ana")
    let second = await fetchScore(for: "bruno")
    return first + second
}

func fetchScore(for player: String) async -> Int {
    try? await Task.sleep(for: .seconds(1))
    return player.count * 10
}

// A task group runs its children concurrently and waits for all of them
func totalScores(for players: [String]) async -> Int {
    await withTaskGroup(of: Int.self) { group in
        for player in players {
            group.addTask { await fetchScore(for: player) }
        }

        var total = 0
        for await score in group {
            total += score
        }
        return total
    }
}

Task {
    print(await totalScores(for: ["ana", "bruno", "carla"]))
}

