import XCTest

struct Cart {
    private(set) var prices: [Double] = []

    mutating func add(price: Double) {
        prices.append(price)
    }

    var total: Double {
        prices.reduce(0, +)
    }
}

final class CartTests: XCTestCase {
    func testTotalAddsLineItems() {
        var cart = Cart()
        cart.add(price: 12.5)
        cart.add(price: 7.5)
        XCTAssertEqual(cart.total, 20.0, accuracy: 0.001)
    }

    func testEmptyCartHasZeroTotal() throws {
        XCTAssertEqual(Cart().total, 0.0)
    }
}

import Testing

func isPalindrome(_ text: String) -> Bool {
    let cleaned = text.lowercased().filter(\.isLetter)
    return cleaned == String(cleaned.reversed())
}

@Test func palindromeDetection() {
    #expect(isPalindrome("A man a plan a canal Panama"))
    #expect(!isPalindrome("swift"))
}

@Test("Short strings are palindromes", arguments: ["", "a", "aa"])
func shortStrings(value: String) {
    #expect(isPalindrome(value))
}

