    private var count = 0

    func bump() {
        count += 1
    }

    func value() -> Int {
        count
    }
}

// Heavy synchronous work should not block the main actor
func checksum(_ bytes: [UInt8]) -> UInt64 {
    bytes.reduce(0) { $0 &+ UInt64($1) }
}
